std::vector<std::uint8_t>EncodeSblrDdlCreateSubscriptionDescriptorV1(const SblrDdlCreateSubscriptionDescriptorV1&v){if(!nz(v.body))return{};std::vector<std::uint8_t>o={'S','L','C','S',1,0,0,0};o.insert(o.end(),v.body.begin(),v.body.end());std::fill(o.begin()+8+344,o.begin()+8+376,0);auto d=sha("ScratchBird.SblrDdlCreateSubscriptionDescriptor.V1",o);std::copy(d.begin(),d.end(),o.begin()+8+344);return o;}bool DecodeSblrDdlCreateSubscriptionDescriptorV1(const std::uint8_t*b,std::size_t n,SblrDdlCreateSubscriptionDescriptorV1*o,std::string*d){if(!o||n!=384||std::memcmp(b,"SLCS",4)||b[4]!=1||b[5]||b[6]||b[7]){if(d)*d="SLCS invalid";return false;}SblrDdlCreateSubscriptionDescriptorV1 v;std::copy_n(b+8,376,v.body.begin());auto e=EncodeSblrDdlCreateSubscriptionDescriptorV1(v);if(e.size()!=384||!std::equal(e.begin(),e.end(),b)){if(d)*d="SLCS hash invalid";return false;}*o=v;return true;}
